from __future__ import annotations

from decimal import Decimal

import pytest
from fastapi import HTTPException

from app.libs.onboarding.schemas import RedemptionDecisionReq
from app.libs.onboarding.service import OnboardingService
from app.models.onboarding import AllotRdmpKind, AllotRdmpStatus
from app.models.pc import ClientSubscription
from app.models.post_trade_allocation import ClientPortfolio

from tests.libs.onboarding.conftest import make_client, make_model, make_portfolio, make_subscription


def _make_redemption_row(svc, *, client, model, multiplier, status):
    return svc.repo.create_allotment(
        user_id=client.id,
        model_id=model.id,
        multiplier=multiplier,
        agg_before=Decimal("0"),
        agg_after=Decimal("0") - multiplier,
        kind=AllotRdmpKind.REDEMPTION,
        status=status,
        note="redemption",
    )


# --- Positive: reject ------------------------------------------------------------------


def test_reject_on_awaiting_pc_sets_terminal_fields_and_leaves_state_untouched(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("10"))
    make_portfolio(session, client, cash_deposit=Decimal("100"), amount_in_trade=Decimal("50"))

    svc = OnboardingService(session)
    row = _make_redemption_row(
        svc, client=client, model=model, multiplier=Decimal("3"), status=AllotRdmpStatus.AWAITING_PC
    )
    session.commit()

    dto = svc.pc_decide_redemption(
        row.id, RedemptionDecisionReq(verdict="reject", reason="not eligible"), decided_by="pc-uid"
    )

    assert dto.status == "rejected"
    fresh = svc.repo.get_allotment(row.id)
    assert fresh.reject_reason == "not eligible"
    assert fresh.decided_by == "pc-uid"
    assert fresh.decided_at is not None

    sub = session.get(ClientSubscription, (client.id, model.id))
    assert sub.multiplier == Decimal("10")
    portfolio = session.get(ClientPortfolio, client.id)
    assert portfolio.cash_deposit == Decimal("100")
    assert portfolio.amount_in_trade == Decimal("50")


# --- Positive: approve, partial redemption ----------------------------------------------


def test_approve_on_awaiting_pc_decrements_subscription_and_shifts_portfolio(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("10"))
    make_portfolio(
        session,
        client,
        cash_deposit=Decimal("100"),
        amount_in_trade=Decimal("300"),
        previous_amount_in_trade=Decimal("300"),
    )

    svc = OnboardingService(session)
    row = _make_redemption_row(
        svc, client=client, model=model, multiplier=Decimal("3"), status=AllotRdmpStatus.AWAITING_PC
    )
    session.commit()

    dto = svc.pc_decide_redemption(
        row.id, RedemptionDecisionReq(verdict="approve"), decided_by="pc-uid"
    )

    assert dto.status == "approved"
    sub = session.get(ClientSubscription, (client.id, model.id))
    assert sub.multiplier == Decimal("7")

    portfolio = session.get(ClientPortfolio, client.id)
    assert portfolio.amount_in_trade == Decimal("297")
    assert portfolio.previous_amount_in_trade == Decimal("297")
    assert portfolio.cash_deposit == Decimal("103")


def test_approve_fully_closing_subscription_sets_multiplier_to_zero(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1"))
    make_subscription(session, client, model, multiplier=Decimal("3"))
    make_portfolio(session, client, amount_in_trade=Decimal("3"), previous_amount_in_trade=Decimal("3"))

    svc = OnboardingService(session)
    row = _make_redemption_row(
        svc, client=client, model=model, multiplier=Decimal("3"), status=AllotRdmpStatus.AWAITING_PC
    )
    session.commit()

    svc.pc_decide_redemption(row.id, RedemptionDecisionReq(verdict="approve"), decided_by="pc-uid")

    # The row is never deleted -- it's the permanent anchor for the client's
    # client_ib_accounts binding, and a later re-subscription is always Add
    # Allotment on this same row, never a new one.
    sub = session.get(ClientSubscription, (client.id, model.id))
    assert sub is not None
    assert sub.multiplier == Decimal("0")


